public:
    int catchMaximumAmountofPeople(vector<int>& team, int dist) {
        int n = team.size();
        int i = 0, j = 0, caught = 0;
        while (i < n && j < n) {
            while (i < n && team[i] != 1) i++;
            while (j < n && team[j] != 0) j++;
            if (i < n && j < n) {
                if (abs(i - j) <= dist) {
                    caught++;
                    i++;
                    j++;
                } else if (j < i - dist) {
                    j++;
                } else {
                    i++;
                }
            }
        }
        return caught;
    }
};

